var particles = [];
var maxAge = 60;
var globalHue = 0;

function setup() {
	createCanvas(1920, 1080);
	colorMode(HSB, 255);
	textAlign(CENTER);
	textSize(20);
	disableScroll();
}

function draw() {
	blendMode(BLEND);
  background(0);
  blendMode(SCREEN);

	let vector = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	vector.sub((window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY))));
	if (vector.mag() > 3) {
		particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
	} else {
		globalHue = random(255);
	}

	for (let i = particles.length -1; i > -1; i--) {
		if (i == particles.length - 1) {
			continue;
		}

		let opacity = map(particles[i].age, 0, maxAge, 0, 255);  // From opaque to transparent.
		let offset = (1 - (particles[i].age / float(maxAge))) * 50  * particles[i].offsetVariance;  // Have it rise the longer it's alive.

		stroke(0, opacity);
		strokeWeight(map(particles[i].age, 0, maxAge, 160, 10) * particles[i].sizeVariance);  // From small to bigger size.
		drawingContext.shadowColor = color(particles[i].hue, 100, 200, opacity);
		drawingContext.shadowBlur = map(particles[i].age, 0, maxAge, 60 * particles[i].sizeVariance, 1);  // From small to large blur.

		let distance = dist(particles[i].pos.x, particles[i].pos.y - offset, 
			particles[i + 1].pos.x, particles[i + 1].pos.y - offset);

		if (distance < 50) line(
			particles[i].pos.x, particles[i].pos.y - offset, 
			particles[i + 1].pos.x, particles[i + 1].pos.y - offset);

		particles[i].age -= 0.2;
		if (particles[i].age <= 0) {
			particles.splice(i, 1);
		}
	}

	drawingContext.shadowBlur = 0;
	fill(255);
	//text("Move the mouse around slowly", width / 2, 40);
}


function disableScroll() { 
    // Get the current page scroll position 
    scrollTop = window.pageYOffset || document.documentElement.scrollTop; 
    scrollLeft = window.pageXOffset || document.documentElement.scrollLeft, 

        // if any scroll is attempted, set this to the previous value 
        window.onscroll = function() { 
            window.scrollTo(scrollLeft, scrollTop); 
        }; 
} 

function enableScroll() { 
    window.onscroll = function() {}; 
}

